#undef SV18
#undef SV19
#undef SV20
#undef SV21
#undef SV22

// K= 23  [intermediate: left+right bnd]
template<typename index_t,typename value_t> __global__
__launch_bounds__(32*CUDTW_TILED_WARPS_PER_BLOCK, CUDTW_TILED_MIN_BLOCKS)
void shfl_FullDTW_Tiled_K23_RW_impl(
    const value_t* __restrict__ Subject, value_t* __restrict__ Dist,
    index_t N, index_t L_query, index_t L_subject, index_t padded_stride,
    const value_t* __restrict__ left_bnd, value_t* __restrict__ right_bnd)
{
    // Multi-warp blocks (item #6): one warp per sequence; lane is intra-warp.
    const index_t lane = threadIdx.x & 31u;
    const index_t warp_in_block = threadIdx.x >> 5;
    const index_t blid = (index_t)blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    if (blid >= N) return;
    const index_t thid=lane, l=lane;
    const index_t base = blid * padded_stride;
    const int Lq = (int)L_query;

    value_t penalty_here0 = INFINITY;
    value_t penalty_here1 = INFINITY;
    value_t penalty_here2 = INFINITY;
    value_t penalty_here3 = INFINITY;
    value_t penalty_here4 = INFINITY;
    value_t penalty_here5 = INFINITY;
    value_t penalty_here6 = INFINITY;
    value_t penalty_here7 = INFINITY;
    value_t penalty_here8 = INFINITY;
    value_t penalty_here9 = INFINITY;
    value_t penalty_here10 = INFINITY;
    value_t penalty_here11 = INFINITY;
    value_t penalty_here12 = INFINITY;
    value_t penalty_here13 = INFINITY;
    value_t penalty_here14 = INFINITY;
    value_t penalty_here15 = INFINITY;
    value_t penalty_here16 = INFINITY;
    value_t penalty_here17 = INFINITY;
    value_t penalty_here18 = INFINITY;
    value_t penalty_here19 = INFINITY;
    value_t penalty_here20 = INFINITY;
    value_t penalty_here21 = INFINITY;
    value_t penalty_here22 = INFINITY;
    value_t penalty_left=INFINITY, penalty_diag=0, penalty_temp0, penalty_temp1;
    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
        penalty_here2 = INFINITY;
        penalty_here3 = INFINITY;
        penalty_here4 = INFINITY;
        penalty_here5 = INFINITY;
        penalty_here6 = INFINITY;
        penalty_here7 = INFINITY;
        penalty_here8 = INFINITY;
        penalty_here9 = INFINITY;
        penalty_here10 = INFINITY;
        penalty_here11 = INFINITY;
        penalty_here12 = INFINITY;
        penalty_here13 = INFINITY;
        penalty_here14 = INFINITY;
        penalty_here15 = INFINITY;
        penalty_here16 = INFINITY;
        penalty_here17 = INFINITY;
        penalty_here18 = INFINITY;
        penalty_here19 = INFINITY;
        penalty_here20 = INFINITY;
        penalty_here21 = INFINITY;
        penalty_here22 = INFINITY;
    }

#if CUDTW_TILED_LDG_SUBJECT
    #define SV0  ((l==0) ? (value_t)0 : __ldg(&Subject[base + 23*l - 1]))
    #define SV1  (__ldg(&Subject[base + 23*l + 0]))
    #define SV2  (__ldg(&Subject[base + 23*l + 1]))
    #define SV3  (__ldg(&Subject[base + 23*l + 2]))
    #define SV4  (__ldg(&Subject[base + 23*l + 3]))
    #define SV5  (__ldg(&Subject[base + 23*l + 4]))
    #define SV6  (__ldg(&Subject[base + 23*l + 5]))
    #define SV7  (__ldg(&Subject[base + 23*l + 6]))
    #define SV8  (__ldg(&Subject[base + 23*l + 7]))
    #define SV9  (__ldg(&Subject[base + 23*l + 8]))
    #define SV10  (__ldg(&Subject[base + 23*l + 9]))
    #define SV11  (__ldg(&Subject[base + 23*l + 10]))
    #define SV12  (__ldg(&Subject[base + 23*l + 11]))
    #define SV13  (__ldg(&Subject[base + 23*l + 12]))
    #define SV14  (__ldg(&Subject[base + 23*l + 13]))
    #define SV15  (__ldg(&Subject[base + 23*l + 14]))
    #define SV16  (__ldg(&Subject[base + 23*l + 15]))
    #define SV17  (__ldg(&Subject[base + 23*l + 16]))
    #define SV18  (__ldg(&Subject[base + 23*l + 17]))
    #define SV19  (__ldg(&Subject[base + 23*l + 18]))
    #define SV20  (__ldg(&Subject[base + 23*l + 19]))
    #define SV21  (__ldg(&Subject[base + 23*l + 20]))
    #define SV22  (__ldg(&Subject[base + 23*l + 21]))
    #define SV23  (__ldg(&Subject[base + 23*l + 22]))
#else
    const value_t sv0 = (l==0) ? (value_t)0 : Subject[base + 23*l - 1];
    const value_t sv1 = Subject[base + 23*l + 0];
    const value_t sv2 = Subject[base + 23*l + 1];
    const value_t sv3 = Subject[base + 23*l + 2];
    const value_t sv4 = Subject[base + 23*l + 3];
    const value_t sv5 = Subject[base + 23*l + 4];
    const value_t sv6 = Subject[base + 23*l + 5];
    const value_t sv7 = Subject[base + 23*l + 6];
    const value_t sv8 = Subject[base + 23*l + 7];
    const value_t sv9 = Subject[base + 23*l + 8];
    const value_t sv10 = Subject[base + 23*l + 9];
    const value_t sv11 = Subject[base + 23*l + 10];
    const value_t sv12 = Subject[base + 23*l + 11];
    const value_t sv13 = Subject[base + 23*l + 12];
    const value_t sv14 = Subject[base + 23*l + 13];
    const value_t sv15 = Subject[base + 23*l + 14];
    const value_t sv16 = Subject[base + 23*l + 15];
    const value_t sv17 = Subject[base + 23*l + 16];
    const value_t sv18 = Subject[base + 23*l + 17];
    const value_t sv19 = Subject[base + 23*l + 18];
    const value_t sv20 = Subject[base + 23*l + 19];
    const value_t sv21 = Subject[base + 23*l + 20];
    const value_t sv22 = Subject[base + 23*l + 21];
    const value_t sv23 = Subject[base + 23*l + 22];
    #define SV0  sv0
    #define SV1  sv1
    #define SV2  sv2
    #define SV3  sv3
    #define SV4  sv4
    #define SV5  sv5
    #define SV6  sv6
    #define SV7  sv7
    #define SV8  sv8
    #define SV9  sv9
    #define SV10  sv10
    #define SV11  sv11
    #define SV12  sv12
    #define SV13  sv13
    #define SV14  sv14
    #define SV15  sv15
    #define SV16  sv16
    #define SV17  sv17
    #define SV18  sv18
    #define SV19  sv19
    #define SV20  sv20
    #define SV21  sv21
    #define SV22  sv22
    #define SV23  sv23
#endif

    const int tgt_t = (int)(L_subject / 23);
    const int tgt_r = (int)(L_subject % 23);
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t cnt = 1;
    value_t qv = INFINITY, nqv = cQuery[thid];
    if (thid == 0) qv = nqv;
    if (thid == 0 && !left_bnd) penalty_here1 = (value_t)0;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);

    // ── Tile left-boundary (seam) injection ──────────────────────────
    // FIX (tiled boundary #1,#2): the seam left_bnd[i] = dp[i][last_col
    // of previous tile] must become the LEFT neighbour of this tile's
    // real column 0. Real col 0 is penalty_here1 on lane 0; its left
    // neighbour is penalty_here0 on lane 0 (the phantom sv0=0 column).
    // So we OVERWRITE penalty_here0 on lane 0 with seam[row] right after
    // it is recomputed each anti-diagonal. Schedule (proven in sim):
    //   pre-loop      -> row 0
    //   main loop k   -> row (k-2)
    // The diagonal for col 0 at row i is then seam[i-1], which arrives
    // automatically via penalty_temp0 (= previous step's penalty_here0).

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)(0);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = INFINITY;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
    qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
    if (thid == 0) qv = nqv;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
    cnt++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here22, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (cnt % 32 == 0) nqv = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)((int)k - 2);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = penalty_here1;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        // Write right boundary from thread 31 (last real col of tile)
        if (thid == 31 && right_bnd) {
            int rr = (int)k - 2 - 31;
            if (rr >= 0 && rr < Lq) right_bnd[blid * Lq + rr] = penalty_here22;
        }
        qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
        if (thid == 0) qv = nqv;
        nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
        cnt++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here22, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    { value_t result = (value_t)0;
      if ((int)thid == tgt_t) {
          if (tgt_r == 0) result = penalty_here0;
          if (tgt_r == 1) result = penalty_here1;
          if (tgt_r == 2) result = penalty_here2;
          if (tgt_r == 3) result = penalty_here3;
          if (tgt_r == 4) result = penalty_here4;
          if (tgt_r == 5) result = penalty_here5;
          if (tgt_r == 6) result = penalty_here6;
          if (tgt_r == 7) result = penalty_here7;
          if (tgt_r == 8) result = penalty_here8;
          if (tgt_r == 9) result = penalty_here9;
          if (tgt_r == 10) result = penalty_here10;
          if (tgt_r == 11) result = penalty_here11;
          if (tgt_r == 12) result = penalty_here12;
          if (tgt_r == 13) result = penalty_here13;
          if (tgt_r == 14) result = penalty_here14;
          if (tgt_r == 15) result = penalty_here15;
          if (tgt_r == 16) result = penalty_here16;
          if (tgt_r == 17) result = penalty_here17;
          if (tgt_r == 18) result = penalty_here18;
          if (tgt_r == 19) result = penalty_here19;
          if (tgt_r == 20) result = penalty_here20;
          if (tgt_r == 21) result = penalty_here21;
          if (tgt_r == 22) result = penalty_here22;
      }
      result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
    }
}
#undef SV0
#undef SV1
#undef SV2
