#undef SV13
#undef SV14
#undef SV15
#undef SV16
#undef SV17
#undef SV18
#undef SV19
#undef SV20
#undef SV21
#undef SV22
#undef SV23
#undef SV24

// K= 25  [intermediate: left+right bnd]
template<typename index_t,typename value_t> __global__
__launch_bounds__(32*CUDTW_TILED_WARPS_PER_BLOCK, CUDTW_TILED_MIN_BLOCKS)
void shfl_FullDTW_Tiled_K25_RW_impl(
    const value_t* __restrict__ Subject, value_t* __restrict__ Dist,
    index_t N, index_t L_query, index_t L_subject, index_t padded_stride,
    const value_t* __restrict__ left_bnd, value_t* __restrict__ right_bnd)
{
    // Multi-warp blocks (item #6): one warp per sequence; lane is intra-warp.
    const index_t lane = threadIdx.x & 31u;
    const index_t warp_in_block = threadIdx.x >> 5;
    const index_t blid = (index_t)blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    if (blid >= N) return;
    const index_t thid=lane, l=lane;
    const index_t base = blid * padded_stride;
    const int Lq = (int)L_query;

    value_t penalty_here0 = INFINITY;
    value_t penalty_here1 = INFINITY;
    value_t penalty_here2 = INFINITY;
    value_t penalty_here3 = INFINITY;
    value_t penalty_here4 = INFINITY;
    value_t penalty_here5 = INFINITY;
    value_t penalty_here6 = INFINITY;
    value_t penalty_here7 = INFINITY;
    value_t penalty_here8 = INFINITY;
    value_t penalty_here9 = INFINITY;
    value_t penalty_here10 = INFINITY;
    value_t penalty_here11 = INFINITY;
    value_t penalty_here12 = INFINITY;
    value_t penalty_here13 = INFINITY;
    value_t penalty_here14 = INFINITY;
    value_t penalty_here15 = INFINITY;
    value_t penalty_here16 = INFINITY;
    value_t penalty_here17 = INFINITY;
    value_t penalty_here18 = INFINITY;
    value_t penalty_here19 = INFINITY;
    value_t penalty_here20 = INFINITY;
    value_t penalty_here21 = INFINITY;
    value_t penalty_here22 = INFINITY;
    value_t penalty_here23 = INFINITY;
    value_t penalty_here24 = INFINITY;
    value_t penalty_left=INFINITY, penalty_diag=0, penalty_temp0, penalty_temp1;
    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
        penalty_here2 = INFINITY;
        penalty_here3 = INFINITY;
        penalty_here4 = INFINITY;
        penalty_here5 = INFINITY;
        penalty_here6 = INFINITY;
        penalty_here7 = INFINITY;
        penalty_here8 = INFINITY;
        penalty_here9 = INFINITY;
        penalty_here10 = INFINITY;
        penalty_here11 = INFINITY;
        penalty_here12 = INFINITY;
        penalty_here13 = INFINITY;
        penalty_here14 = INFINITY;
        penalty_here15 = INFINITY;
        penalty_here16 = INFINITY;
        penalty_here17 = INFINITY;
        penalty_here18 = INFINITY;
        penalty_here19 = INFINITY;
        penalty_here20 = INFINITY;
        penalty_here21 = INFINITY;
        penalty_here22 = INFINITY;
        penalty_here23 = INFINITY;
        penalty_here24 = INFINITY;
    }

#if CUDTW_TILED_LDG_SUBJECT
    #define SV0  ((l==0) ? (value_t)0 : __ldg(&Subject[base + 25*l - 1]))
    #define SV1  (__ldg(&Subject[base + 25*l + 0]))
    #define SV2  (__ldg(&Subject[base + 25*l + 1]))
    #define SV3  (__ldg(&Subject[base + 25*l + 2]))
    #define SV4  (__ldg(&Subject[base + 25*l + 3]))
    #define SV5  (__ldg(&Subject[base + 25*l + 4]))
    #define SV6  (__ldg(&Subject[base + 25*l + 5]))
    #define SV7  (__ldg(&Subject[base + 25*l + 6]))
    #define SV8  (__ldg(&Subject[base + 25*l + 7]))
    #define SV9  (__ldg(&Subject[base + 25*l + 8]))
    #define SV10  (__ldg(&Subject[base + 25*l + 9]))
    #define SV11  (__ldg(&Subject[base + 25*l + 10]))
    #define SV12  (__ldg(&Subject[base + 25*l + 11]))
    #define SV13  (__ldg(&Subject[base + 25*l + 12]))
    #define SV14  (__ldg(&Subject[base + 25*l + 13]))
    #define SV15  (__ldg(&Subject[base + 25*l + 14]))
    #define SV16  (__ldg(&Subject[base + 25*l + 15]))
    #define SV17  (__ldg(&Subject[base + 25*l + 16]))
    #define SV18  (__ldg(&Subject[base + 25*l + 17]))
    #define SV19  (__ldg(&Subject[base + 25*l + 18]))
    #define SV20  (__ldg(&Subject[base + 25*l + 19]))
    #define SV21  (__ldg(&Subject[base + 25*l + 20]))
    #define SV22  (__ldg(&Subject[base + 25*l + 21]))
    #define SV23  (__ldg(&Subject[base + 25*l + 22]))
    #define SV24  (__ldg(&Subject[base + 25*l + 23]))
    #define SV25  (__ldg(&Subject[base + 25*l + 24]))
#else
    const value_t sv0 = (l==0) ? (value_t)0 : Subject[base + 25*l - 1];
    const value_t sv1 = Subject[base + 25*l + 0];
    const value_t sv2 = Subject[base + 25*l + 1];
    const value_t sv3 = Subject[base + 25*l + 2];
    const value_t sv4 = Subject[base + 25*l + 3];
    const value_t sv5 = Subject[base + 25*l + 4];
    const value_t sv6 = Subject[base + 25*l + 5];
    const value_t sv7 = Subject[base + 25*l + 6];
    const value_t sv8 = Subject[base + 25*l + 7];
    const value_t sv9 = Subject[base + 25*l + 8];
    const value_t sv10 = Subject[base + 25*l + 9];
    const value_t sv11 = Subject[base + 25*l + 10];
    const value_t sv12 = Subject[base + 25*l + 11];
    const value_t sv13 = Subject[base + 25*l + 12];
    const value_t sv14 = Subject[base + 25*l + 13];
    const value_t sv15 = Subject[base + 25*l + 14];
    const value_t sv16 = Subject[base + 25*l + 15];
    const value_t sv17 = Subject[base + 25*l + 16];
    const value_t sv18 = Subject[base + 25*l + 17];
    const value_t sv19 = Subject[base + 25*l + 18];
    const value_t sv20 = Subject[base + 25*l + 19];
    const value_t sv21 = Subject[base + 25*l + 20];
    const value_t sv22 = Subject[base + 25*l + 21];
    const value_t sv23 = Subject[base + 25*l + 22];
    const value_t sv24 = Subject[base + 25*l + 23];
    const value_t sv25 = Subject[base + 25*l + 24];
    #define SV0  sv0
    #define SV1  sv1
    #define SV2  sv2
    #define SV3  sv3
    #define SV4  sv4
    #define SV5  sv5
    #define SV6  sv6
    #define SV7  sv7
    #define SV8  sv8
    #define SV9  sv9
    #define SV10  sv10
    #define SV11  sv11
    #define SV12  sv12
    #define SV13  sv13
    #define SV14  sv14
    #define SV15  sv15
    #define SV16  sv16
    #define SV17  sv17
    #define SV18  sv18
    #define SV19  sv19
    #define SV20  sv20
    #define SV21  sv21
    #define SV22  sv22
    #define SV23  sv23
    #define SV24  sv24
    #define SV25  sv25
#endif

    const int tgt_t = (int)(L_subject / 25);
    const int tgt_r = (int)(L_subject % 25);
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t cnt = 1;
    value_t qv = INFINITY, nqv = cQuery[thid];
    if (thid == 0) qv = nqv;
    if (thid == 0 && !left_bnd) penalty_here1 = (value_t)0;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);

    // ── Tile left-boundary (seam) injection ──────────────────────────
    // FIX (tiled boundary #1,#2): the seam left_bnd[i] = dp[i][last_col
    // of previous tile] must become the LEFT neighbour of this tile's
    // real column 0. Real col 0 is penalty_here1 on lane 0; its left
    // neighbour is penalty_here0 on lane 0 (the phantom sv0=0 column).
    // So we OVERWRITE penalty_here0 on lane 0 with seam[row] right after
    // it is recomputed each anti-diagonal. Schedule (proven in sim):
    //   pre-loop      -> row 0
    //   main loop k   -> row (k-2)
    // The diagonal for col 0 at row i is then seam[i-1], which arrives
    // automatically via penalty_temp0 (= previous step's penalty_here0).

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)(0);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = INFINITY;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
    qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
    if (thid == 0) qv = nqv;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
    cnt++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here24, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (cnt % 32 == 0) nqv = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)((int)k - 2);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = penalty_here1;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
        // Write right boundary from thread 31 (last real col of tile)
        if (thid == 31 && right_bnd) {
            int rr = (int)k - 2 - 31;
            if (rr >= 0 && rr < Lq) right_bnd[blid * Lq + rr] = penalty_here24;
        }
        qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
        if (thid == 0) qv = nqv;
        nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
        cnt++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here24, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    { value_t result = (value_t)0;
      if ((int)thid == tgt_t) {
          if (tgt_r == 0) result = penalty_here0;
          if (tgt_r == 1) result = penalty_here1;
          if (tgt_r == 2) result = penalty_here2;
          if (tgt_r == 3) result = penalty_here3;
          if (tgt_r == 4) result = penalty_here4;
          if (tgt_r == 5) result = penalty_here5;
          if (tgt_r == 6) result = penalty_here6;
          if (tgt_r == 7) result = penalty_here7;
          if (tgt_r == 8) result = penalty_here8;
          if (tgt_r == 9) result = penalty_here9;
          if (tgt_r == 10) result = penalty_here10;
          if (tgt_r == 11) result = penalty_here11;
          if (tgt_r == 12) result = penalty_here12;
          if (tgt_r == 13) result = penalty_here13;
          if (tgt_r == 14) result = penalty_here14;
          if (tgt_r == 15) result = penalty_here15;
          if (tgt_r == 16) result = penalty_here16;
          if (tgt_r == 17) result = penalty_here17;
          if (tgt_r == 18) result = penalty_here18;
          if (tgt_r == 19) result = penalty_here19;
          if (tgt_r == 20) result = penalty_here20;
          if (tgt_r == 21) result = penalty_here21;
          if (tgt_r == 22) result = penalty_here22;
          if (tgt_r == 23) result = penalty_here23;
          if (tgt_r == 24) result = penalty_here24;
      }
      result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
    }
}
#undef SV0
#undef SV1
#undef SV2
#undef SV3
#undef SV4
#undef SV5
#undef SV6
#undef SV7
#undef SV8
#undef SV9
#undef SV10
#undef SV11
#undef SV12
#undef SV13
#undef SV14
#undef SV15
#undef SV16
#undef SV17
#undef SV18
#undef SV19
#undef SV20
#undef SV21
#undef SV22
#undef SV23
#undef SV24
#undef SV25

// K= 26  [intermediate: left+right bnd]
template<typename index_t,typename value_t> __global__
__launch_bounds__(32*CUDTW_TILED_WARPS_PER_BLOCK, CUDTW_TILED_MIN_BLOCKS)
void shfl_FullDTW_Tiled_K26_RW_impl(
    const value_t* __restrict__ Subject, value_t* __restrict__ Dist,
    index_t N, index_t L_query, index_t L_subject, index_t padded_stride,
    const value_t* __restrict__ left_bnd, value_t* __restrict__ right_bnd)
{
    // Multi-warp blocks (item #6): one warp per sequence; lane is intra-warp.
    const index_t lane = threadIdx.x & 31u;
    const index_t warp_in_block = threadIdx.x >> 5;
    const index_t blid = (index_t)blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    if (blid >= N) return;
    const index_t thid=lane, l=lane;
    const index_t base = blid * padded_stride;
    const int Lq = (int)L_query;

    value_t penalty_here0 = INFINITY;
    value_t penalty_here1 = INFINITY;
    value_t penalty_here2 = INFINITY;
    value_t penalty_here3 = INFINITY;
    value_t penalty_here4 = INFINITY;
    value_t penalty_here5 = INFINITY;
    value_t penalty_here6 = INFINITY;
    value_t penalty_here7 = INFINITY;
    value_t penalty_here8 = INFINITY;
    value_t penalty_here9 = INFINITY;
    value_t penalty_here10 = INFINITY;
    value_t penalty_here11 = INFINITY;
    value_t penalty_here12 = INFINITY;
    value_t penalty_here13 = INFINITY;
    value_t penalty_here14 = INFINITY;
    value_t penalty_here15 = INFINITY;
    value_t penalty_here16 = INFINITY;
    value_t penalty_here17 = INFINITY;
    value_t penalty_here18 = INFINITY;
    value_t penalty_here19 = INFINITY;
    value_t penalty_here20 = INFINITY;
    value_t penalty_here21 = INFINITY;
    value_t penalty_here22 = INFINITY;
    value_t penalty_here23 = INFINITY;
    value_t penalty_here24 = INFINITY;
    value_t penalty_here25 = INFINITY;
    value_t penalty_left=INFINITY, penalty_diag=0, penalty_temp0, penalty_temp1;
    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
        penalty_here2 = INFINITY;
        penalty_here3 = INFINITY;
        penalty_here4 = INFINITY;
        penalty_here5 = INFINITY;
        penalty_here6 = INFINITY;
        penalty_here7 = INFINITY;
        penalty_here8 = INFINITY;
        penalty_here9 = INFINITY;
        penalty_here10 = INFINITY;
        penalty_here11 = INFINITY;
        penalty_here12 = INFINITY;
        penalty_here13 = INFINITY;
        penalty_here14 = INFINITY;
        penalty_here15 = INFINITY;
        penalty_here16 = INFINITY;
        penalty_here17 = INFINITY;
        penalty_here18 = INFINITY;
        penalty_here19 = INFINITY;
        penalty_here20 = INFINITY;
        penalty_here21 = INFINITY;
        penalty_here22 = INFINITY;
        penalty_here23 = INFINITY;
        penalty_here24 = INFINITY;
        penalty_here25 = INFINITY;
    }

#if CUDTW_TILED_LDG_SUBJECT
    #define SV0  ((l==0) ? (value_t)0 : __ldg(&Subject[base + 26*l - 1]))
    #define SV1  (__ldg(&Subject[base + 26*l + 0]))
    #define SV2  (__ldg(&Subject[base + 26*l + 1]))
    #define SV3  (__ldg(&Subject[base + 26*l + 2]))
    #define SV4  (__ldg(&Subject[base + 26*l + 3]))
    #define SV5  (__ldg(&Subject[base + 26*l + 4]))
    #define SV6  (__ldg(&Subject[base + 26*l + 5]))
    #define SV7  (__ldg(&Subject[base + 26*l + 6]))
    #define SV8  (__ldg(&Subject[base + 26*l + 7]))
    #define SV9  (__ldg(&Subject[base + 26*l + 8]))
    #define SV10  (__ldg(&Subject[base + 26*l + 9]))
    #define SV11  (__ldg(&Subject[base + 26*l + 10]))
    #define SV12  (__ldg(&Subject[base + 26*l + 11]))
    #define SV13  (__ldg(&Subject[base + 26*l + 12]))
    #define SV14  (__ldg(&Subject[base + 26*l + 13]))
    #define SV15  (__ldg(&Subject[base + 26*l + 14]))
    #define SV16  (__ldg(&Subject[base + 26*l + 15]))
    #define SV17  (__ldg(&Subject[base + 26*l + 16]))
    #define SV18  (__ldg(&Subject[base + 26*l + 17]))
    #define SV19  (__ldg(&Subject[base + 26*l + 18]))
    #define SV20  (__ldg(&Subject[base + 26*l + 19]))
    #define SV21  (__ldg(&Subject[base + 26*l + 20]))
    #define SV22  (__ldg(&Subject[base + 26*l + 21]))
    #define SV23  (__ldg(&Subject[base + 26*l + 22]))
    #define SV24  (__ldg(&Subject[base + 26*l + 23]))
    #define SV25  (__ldg(&Subject[base + 26*l + 24]))
    #define SV26  (__ldg(&Subject[base + 26*l + 25]))
#else
    const value_t sv0 = (l==0) ? (value_t)0 : Subject[base + 26*l - 1];
    const value_t sv1 = Subject[base + 26*l + 0];
    const value_t sv2 = Subject[base + 26*l + 1];
    const value_t sv3 = Subject[base + 26*l + 2];
    const value_t sv4 = Subject[base + 26*l + 3];
    const value_t sv5 = Subject[base + 26*l + 4];
    const value_t sv6 = Subject[base + 26*l + 5];
    const value_t sv7 = Subject[base + 26*l + 6];
    const value_t sv8 = Subject[base + 26*l + 7];
    const value_t sv9 = Subject[base + 26*l + 8];
    const value_t sv10 = Subject[base + 26*l + 9];
    const value_t sv11 = Subject[base + 26*l + 10];
    const value_t sv12 = Subject[base + 26*l + 11];
    const value_t sv13 = Subject[base + 26*l + 12];
    const value_t sv14 = Subject[base + 26*l + 13];
    const value_t sv15 = Subject[base + 26*l + 14];
    const value_t sv16 = Subject[base + 26*l + 15];
    const value_t sv17 = Subject[base + 26*l + 16];
    const value_t sv18 = Subject[base + 26*l + 17];
    const value_t sv19 = Subject[base + 26*l + 18];
    const value_t sv20 = Subject[base + 26*l + 19];
    const value_t sv21 = Subject[base + 26*l + 20];
    const value_t sv22 = Subject[base + 26*l + 21];
    const value_t sv23 = Subject[base + 26*l + 22];
    const value_t sv24 = Subject[base + 26*l + 23];
    const value_t sv25 = Subject[base + 26*l + 24];
    const value_t sv26 = Subject[base + 26*l + 25];
    #define SV0  sv0
    #define SV1  sv1
    #define SV2  sv2
    #define SV3  sv3
    #define SV4  sv4
    #define SV5  sv5
    #define SV6  sv6
    #define SV7  sv7
    #define SV8  sv8
    #define SV9  sv9
    #define SV10  sv10
    #define SV11  sv11
    #define SV12  sv12
    #define SV13  sv13
    #define SV14  sv14
    #define SV15  sv15
    #define SV16  sv16
    #define SV17  sv17
    #define SV18  sv18
    #define SV19  sv19
    #define SV20  sv20
    #define SV21  sv21
    #define SV22  sv22
    #define SV23  sv23
    #define SV24  sv24
    #define SV25  sv25
    #define SV26  sv26
#endif

    const int tgt_t = (int)(L_subject / 26);
    const int tgt_r = (int)(L_subject % 26);
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t cnt = 1;
    value_t qv = INFINITY, nqv = cQuery[thid];
    if (thid == 0) qv = nqv;
    if (thid == 0 && !left_bnd) penalty_here1 = (value_t)0;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);

    // ── Tile left-boundary (seam) injection ──────────────────────────
    // FIX (tiled boundary #1,#2): the seam left_bnd[i] = dp[i][last_col
    // of previous tile] must become the LEFT neighbour of this tile's
    // real column 0. Real col 0 is penalty_here1 on lane 0; its left
    // neighbour is penalty_here0 on lane 0 (the phantom sv0=0 column).
    // So we OVERWRITE penalty_here0 on lane 0 with seam[row] right after
    // it is recomputed each anti-diagonal. Schedule (proven in sim):
    //   pre-loop      -> row 0
    //   main loop k   -> row (k-2)
    // The diagonal for col 0 at row i is then seam[i-1], which arrives
    // automatically via penalty_temp0 (= previous step's penalty_here0).

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)(0);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = INFINITY;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_temp0 = penalty_here24;
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
        penalty_here25 = (qv-SV25)*(qv-SV25) + min(penalty_here24, min(penalty_here25, penalty_temp0));
    qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
    if (thid == 0) qv = nqv;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
    cnt++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here25, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (cnt % 32 == 0) nqv = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)((int)k - 2);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = penalty_here1;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_temp0 = penalty_here24;
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
        penalty_here25 = (qv-SV25)*(qv-SV25) + min(penalty_here24, min(penalty_here25, penalty_temp0));
        // Write right boundary from thread 31 (last real col of tile)
        if (thid == 31 && right_bnd) {
            int rr = (int)k - 2 - 31;
            if (rr >= 0 && rr < Lq) right_bnd[blid * Lq + rr] = penalty_here25;
        }
        qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
        if (thid == 0) qv = nqv;
        nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
        cnt++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here25, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    { value_t result = (value_t)0;
      if ((int)thid == tgt_t) {
          if (tgt_r == 0) result = penalty_here0;
          if (tgt_r == 1) result = penalty_here1;
          if (tgt_r == 2) result = penalty_here2;
          if (tgt_r == 3) result = penalty_here3;
          if (tgt_r == 4) result = penalty_here4;
          if (tgt_r == 5) result = penalty_here5;
          if (tgt_r == 6) result = penalty_here6;
          if (tgt_r == 7) result = penalty_here7;
          if (tgt_r == 8) result = penalty_here8;
          if (tgt_r == 9) result = penalty_here9;
          if (tgt_r == 10) result = penalty_here10;
          if (tgt_r == 11) result = penalty_here11;
          if (tgt_r == 12) result = penalty_here12;
          if (tgt_r == 13) result = penalty_here13;
          if (tgt_r == 14) result = penalty_here14;
          if (tgt_r == 15) result = penalty_here15;
          if (tgt_r == 16) result = penalty_here16;
          if (tgt_r == 17) result = penalty_here17;
          if (tgt_r == 18) result = penalty_here18;
          if (tgt_r == 19) result = penalty_here19;
          if (tgt_r == 20) result = penalty_here20;
          if (tgt_r == 21) result = penalty_here21;
          if (tgt_r == 22) result = penalty_here22;
          if (tgt_r == 23) result = penalty_here23;
          if (tgt_r == 24) result = penalty_here24;
          if (tgt_r == 25) result = penalty_here25;
      }
      result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
    }
}
#undef SV0
#undef SV1
#undef SV2
#undef SV3
#undef SV4
#undef SV5
#undef SV6
#undef SV7
#undef SV8
#undef SV9
#undef SV10
#undef SV11
#undef SV12
#undef SV13
#undef SV14
#undef SV15
#undef SV16
#undef SV17
#undef SV18
#undef SV19
#undef SV20
#undef SV21
#undef SV22
#undef SV23
#undef SV24
#undef SV25
#undef SV26

// K= 27  [intermediate: left+right bnd]
template<typename index_t,typename value_t> __global__
__launch_bounds__(32*CUDTW_TILED_WARPS_PER_BLOCK, CUDTW_TILED_MIN_BLOCKS)
void shfl_FullDTW_Tiled_K27_RW_impl(
    const value_t* __restrict__ Subject, value_t* __restrict__ Dist,
    index_t N, index_t L_query, index_t L_subject, index_t padded_stride,
    const value_t* __restrict__ left_bnd, value_t* __restrict__ right_bnd)
{
    // Multi-warp blocks (item #6): one warp per sequence; lane is intra-warp.
    const index_t lane = threadIdx.x & 31u;
    const index_t warp_in_block = threadIdx.x >> 5;
    const index_t blid = (index_t)blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    if (blid >= N) return;
    const index_t thid=lane, l=lane;
    const index_t base = blid * padded_stride;
    const int Lq = (int)L_query;

    value_t penalty_here0 = INFINITY;
    value_t penalty_here1 = INFINITY;
    value_t penalty_here2 = INFINITY;
    value_t penalty_here3 = INFINITY;
    value_t penalty_here4 = INFINITY;
    value_t penalty_here5 = INFINITY;
    value_t penalty_here6 = INFINITY;
    value_t penalty_here7 = INFINITY;
    value_t penalty_here8 = INFINITY;
    value_t penalty_here9 = INFINITY;
    value_t penalty_here10 = INFINITY;
    value_t penalty_here11 = INFINITY;
    value_t penalty_here12 = INFINITY;
    value_t penalty_here13 = INFINITY;
    value_t penalty_here14 = INFINITY;
    value_t penalty_here15 = INFINITY;
    value_t penalty_here16 = INFINITY;
    value_t penalty_here17 = INFINITY;
    value_t penalty_here18 = INFINITY;
    value_t penalty_here19 = INFINITY;
    value_t penalty_here20 = INFINITY;
    value_t penalty_here21 = INFINITY;
    value_t penalty_here22 = INFINITY;
    value_t penalty_here23 = INFINITY;
    value_t penalty_here24 = INFINITY;
    value_t penalty_here25 = INFINITY;
    value_t penalty_here26 = INFINITY;
    value_t penalty_left=INFINITY, penalty_diag=0, penalty_temp0, penalty_temp1;
    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
        penalty_here2 = INFINITY;
        penalty_here3 = INFINITY;
        penalty_here4 = INFINITY;
        penalty_here5 = INFINITY;
        penalty_here6 = INFINITY;
        penalty_here7 = INFINITY;
        penalty_here8 = INFINITY;
        penalty_here9 = INFINITY;
        penalty_here10 = INFINITY;
        penalty_here11 = INFINITY;
        penalty_here12 = INFINITY;
        penalty_here13 = INFINITY;
        penalty_here14 = INFINITY;
        penalty_here15 = INFINITY;
        penalty_here16 = INFINITY;
        penalty_here17 = INFINITY;
        penalty_here18 = INFINITY;
        penalty_here19 = INFINITY;
        penalty_here20 = INFINITY;
        penalty_here21 = INFINITY;
        penalty_here22 = INFINITY;
        penalty_here23 = INFINITY;
        penalty_here24 = INFINITY;
        penalty_here25 = INFINITY;
        penalty_here26 = INFINITY;
    }

#if CUDTW_TILED_LDG_SUBJECT
    #define SV0  ((l==0) ? (value_t)0 : __ldg(&Subject[base + 27*l - 1]))
    #define SV1  (__ldg(&Subject[base + 27*l + 0]))
    #define SV2  (__ldg(&Subject[base + 27*l + 1]))
    #define SV3  (__ldg(&Subject[base + 27*l + 2]))
    #define SV4  (__ldg(&Subject[base + 27*l + 3]))
    #define SV5  (__ldg(&Subject[base + 27*l + 4]))
    #define SV6  (__ldg(&Subject[base + 27*l + 5]))
    #define SV7  (__ldg(&Subject[base + 27*l + 6]))
    #define SV8  (__ldg(&Subject[base + 27*l + 7]))
    #define SV9  (__ldg(&Subject[base + 27*l + 8]))
    #define SV10  (__ldg(&Subject[base + 27*l + 9]))
    #define SV11  (__ldg(&Subject[base + 27*l + 10]))
    #define SV12  (__ldg(&Subject[base + 27*l + 11]))
    #define SV13  (__ldg(&Subject[base + 27*l + 12]))
    #define SV14  (__ldg(&Subject[base + 27*l + 13]))
    #define SV15  (__ldg(&Subject[base + 27*l + 14]))
    #define SV16  (__ldg(&Subject[base + 27*l + 15]))
    #define SV17  (__ldg(&Subject[base + 27*l + 16]))
    #define SV18  (__ldg(&Subject[base + 27*l + 17]))
    #define SV19  (__ldg(&Subject[base + 27*l + 18]))
    #define SV20  (__ldg(&Subject[base + 27*l + 19]))
    #define SV21  (__ldg(&Subject[base + 27*l + 20]))
    #define SV22  (__ldg(&Subject[base + 27*l + 21]))
    #define SV23  (__ldg(&Subject[base + 27*l + 22]))
    #define SV24  (__ldg(&Subject[base + 27*l + 23]))
    #define SV25  (__ldg(&Subject[base + 27*l + 24]))
    #define SV26  (__ldg(&Subject[base + 27*l + 25]))
    #define SV27  (__ldg(&Subject[base + 27*l + 26]))
#else
    const value_t sv0 = (l==0) ? (value_t)0 : Subject[base + 27*l - 1];
    const value_t sv1 = Subject[base + 27*l + 0];
    const value_t sv2 = Subject[base + 27*l + 1];
    const value_t sv3 = Subject[base + 27*l + 2];
    const value_t sv4 = Subject[base + 27*l + 3];
    const value_t sv5 = Subject[base + 27*l + 4];
    const value_t sv6 = Subject[base + 27*l + 5];
    const value_t sv7 = Subject[base + 27*l + 6];
    const value_t sv8 = Subject[base + 27*l + 7];
    const value_t sv9 = Subject[base + 27*l + 8];
    const value_t sv10 = Subject[base + 27*l + 9];
    const value_t sv11 = Subject[base + 27*l + 10];
    const value_t sv12 = Subject[base + 27*l + 11];
    const value_t sv13 = Subject[base + 27*l + 12];
    const value_t sv14 = Subject[base + 27*l + 13];
    const value_t sv15 = Subject[base + 27*l + 14];
    const value_t sv16 = Subject[base + 27*l + 15];
    const value_t sv17 = Subject[base + 27*l + 16];
    const value_t sv18 = Subject[base + 27*l + 17];
    const value_t sv19 = Subject[base + 27*l + 18];
    const value_t sv20 = Subject[base + 27*l + 19];
    const value_t sv21 = Subject[base + 27*l + 20];
    const value_t sv22 = Subject[base + 27*l + 21];
    const value_t sv23 = Subject[base + 27*l + 22];
    const value_t sv24 = Subject[base + 27*l + 23];
    const value_t sv25 = Subject[base + 27*l + 24];
    const value_t sv26 = Subject[base + 27*l + 25];
    const value_t sv27 = Subject[base + 27*l + 26];
    #define SV0  sv0
    #define SV1  sv1
    #define SV2  sv2
    #define SV3  sv3
    #define SV4  sv4
    #define SV5  sv5
    #define SV6  sv6
    #define SV7  sv7
    #define SV8  sv8
    #define SV9  sv9
    #define SV10  sv10
    #define SV11  sv11
    #define SV12  sv12
    #define SV13  sv13
    #define SV14  sv14
    #define SV15  sv15
    #define SV16  sv16
    #define SV17  sv17
    #define SV18  sv18
    #define SV19  sv19
    #define SV20  sv20
    #define SV21  sv21
    #define SV22  sv22
    #define SV23  sv23
    #define SV24  sv24
    #define SV25  sv25
    #define SV26  sv26
    #define SV27  sv27
#endif

    const int tgt_t = (int)(L_subject / 27);
    const int tgt_r = (int)(L_subject % 27);
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t cnt = 1;
    value_t qv = INFINITY, nqv = cQuery[thid];
    if (thid == 0) qv = nqv;
    if (thid == 0 && !left_bnd) penalty_here1 = (value_t)0;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);

    // ── Tile left-boundary (seam) injection ──────────────────────────
    // FIX (tiled boundary #1,#2): the seam left_bnd[i] = dp[i][last_col
    // of previous tile] must become the LEFT neighbour of this tile's
    // real column 0. Real col 0 is penalty_here1 on lane 0; its left
    // neighbour is penalty_here0 on lane 0 (the phantom sv0=0 column).
    // So we OVERWRITE penalty_here0 on lane 0 with seam[row] right after
    // it is recomputed each anti-diagonal. Schedule (proven in sim):
    //   pre-loop      -> row 0
    //   main loop k   -> row (k-2)
    // The diagonal for col 0 at row i is then seam[i-1], which arrives
    // automatically via penalty_temp0 (= previous step's penalty_here0).

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)(0);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = INFINITY;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_temp0 = penalty_here24;
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
        penalty_temp1 = penalty_here25;
        penalty_here25 = (qv-SV25)*(qv-SV25) + min(penalty_here24, min(penalty_here25, penalty_temp0));
        penalty_here26 = (qv-SV26)*(qv-SV26) + min(penalty_here25, min(penalty_here26, penalty_temp1));
    qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
    if (thid == 0) qv = nqv;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
    cnt++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here26, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (cnt % 32 == 0) nqv = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)((int)k - 2);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = penalty_here1;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_temp0 = penalty_here24;
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
        penalty_temp1 = penalty_here25;
        penalty_here25 = (qv-SV25)*(qv-SV25) + min(penalty_here24, min(penalty_here25, penalty_temp0));
        penalty_here26 = (qv-SV26)*(qv-SV26) + min(penalty_here25, min(penalty_here26, penalty_temp1));
        // Write right boundary from thread 31 (last real col of tile)
        if (thid == 31 && right_bnd) {
            int rr = (int)k - 2 - 31;
            if (rr >= 0 && rr < Lq) right_bnd[blid * Lq + rr] = penalty_here26;
        }
        qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
        if (thid == 0) qv = nqv;
        nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
        cnt++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here26, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    { value_t result = (value_t)0;
      if ((int)thid == tgt_t) {
          if (tgt_r == 0) result = penalty_here0;
          if (tgt_r == 1) result = penalty_here1;
          if (tgt_r == 2) result = penalty_here2;
          if (tgt_r == 3) result = penalty_here3;
          if (tgt_r == 4) result = penalty_here4;
          if (tgt_r == 5) result = penalty_here5;
          if (tgt_r == 6) result = penalty_here6;
          if (tgt_r == 7) result = penalty_here7;
          if (tgt_r == 8) result = penalty_here8;
          if (tgt_r == 9) result = penalty_here9;
          if (tgt_r == 10) result = penalty_here10;
          if (tgt_r == 11) result = penalty_here11;
          if (tgt_r == 12) result = penalty_here12;
          if (tgt_r == 13) result = penalty_here13;
          if (tgt_r == 14) result = penalty_here14;
          if (tgt_r == 15) result = penalty_here15;
          if (tgt_r == 16) result = penalty_here16;
          if (tgt_r == 17) result = penalty_here17;
          if (tgt_r == 18) result = penalty_here18;
          if (tgt_r == 19) result = penalty_here19;
          if (tgt_r == 20) result = penalty_here20;
          if (tgt_r == 21) result = penalty_here21;
          if (tgt_r == 22) result = penalty_here22;
          if (tgt_r == 23) result = penalty_here23;
          if (tgt_r == 24) result = penalty_here24;
          if (tgt_r == 25) result = penalty_here25;
          if (tgt_r == 26) result = penalty_here26;
      }
      result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
    }
}
#undef SV0
#undef SV1
#undef SV2
#undef SV3
#undef SV4
#undef SV5
#undef SV6
#undef SV7
#undef SV8
#undef SV9
#undef SV10
#undef SV11
#undef SV12
#undef SV13
#undef SV14
#undef SV15
#undef SV16
#undef SV17
#undef SV18
#undef SV19
#undef SV20
#undef SV21
#undef SV22
#undef SV23
#undef SV24
#undef SV25
#undef SV26
#undef SV27

// K= 28  [intermediate: left+right bnd]
template<typename index_t,typename value_t> __global__
__launch_bounds__(32*CUDTW_TILED_WARPS_PER_BLOCK, CUDTW_TILED_MIN_BLOCKS)
void shfl_FullDTW_Tiled_K28_RW_impl(
    const value_t* __restrict__ Subject, value_t* __restrict__ Dist,
    index_t N, index_t L_query, index_t L_subject, index_t padded_stride,
    const value_t* __restrict__ left_bnd, value_t* __restrict__ right_bnd)
{
    // Multi-warp blocks (item #6): one warp per sequence; lane is intra-warp.
    const index_t lane = threadIdx.x & 31u;
    const index_t warp_in_block = threadIdx.x >> 5;
    const index_t blid = (index_t)blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    if (blid >= N) return;
    const index_t thid=lane, l=lane;
    const index_t base = blid * padded_stride;
    const int Lq = (int)L_query;

    value_t penalty_here0 = INFINITY;
    value_t penalty_here1 = INFINITY;
    value_t penalty_here2 = INFINITY;
    value_t penalty_here3 = INFINITY;
    value_t penalty_here4 = INFINITY;
    value_t penalty_here5 = INFINITY;
    value_t penalty_here6 = INFINITY;
    value_t penalty_here7 = INFINITY;
    value_t penalty_here8 = INFINITY;
    value_t penalty_here9 = INFINITY;
    value_t penalty_here10 = INFINITY;
    value_t penalty_here11 = INFINITY;
    value_t penalty_here12 = INFINITY;
    value_t penalty_here13 = INFINITY;
    value_t penalty_here14 = INFINITY;
    value_t penalty_here15 = INFINITY;
    value_t penalty_here16 = INFINITY;
    value_t penalty_here17 = INFINITY;
    value_t penalty_here18 = INFINITY;
    value_t penalty_here19 = INFINITY;
    value_t penalty_here20 = INFINITY;
    value_t penalty_here21 = INFINITY;
    value_t penalty_here22 = INFINITY;
    value_t penalty_here23 = INFINITY;
    value_t penalty_here24 = INFINITY;
    value_t penalty_here25 = INFINITY;
    value_t penalty_here26 = INFINITY;
    value_t penalty_here27 = INFINITY;
    value_t penalty_left=INFINITY, penalty_diag=0, penalty_temp0, penalty_temp1;
    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
        penalty_here2 = INFINITY;
        penalty_here3 = INFINITY;
        penalty_here4 = INFINITY;
        penalty_here5 = INFINITY;
        penalty_here6 = INFINITY;
        penalty_here7 = INFINITY;
        penalty_here8 = INFINITY;
        penalty_here9 = INFINITY;
        penalty_here10 = INFINITY;
        penalty_here11 = INFINITY;
        penalty_here12 = INFINITY;
        penalty_here13 = INFINITY;
        penalty_here14 = INFINITY;
        penalty_here15 = INFINITY;
        penalty_here16 = INFINITY;
        penalty_here17 = INFINITY;
        penalty_here18 = INFINITY;
        penalty_here19 = INFINITY;
        penalty_here20 = INFINITY;
        penalty_here21 = INFINITY;
        penalty_here22 = INFINITY;
        penalty_here23 = INFINITY;
        penalty_here24 = INFINITY;
        penalty_here25 = INFINITY;
        penalty_here26 = INFINITY;
        penalty_here27 = INFINITY;
    }

#if CUDTW_TILED_LDG_SUBJECT
    #define SV0  ((l==0) ? (value_t)0 : __ldg(&Subject[base + 28*l - 1]))
    #define SV1  (__ldg(&Subject[base + 28*l + 0]))
    #define SV2  (__ldg(&Subject[base + 28*l + 1]))
    #define SV3  (__ldg(&Subject[base + 28*l + 2]))
    #define SV4  (__ldg(&Subject[base + 28*l + 3]))
    #define SV5  (__ldg(&Subject[base + 28*l + 4]))
    #define SV6  (__ldg(&Subject[base + 28*l + 5]))
    #define SV7  (__ldg(&Subject[base + 28*l + 6]))
    #define SV8  (__ldg(&Subject[base + 28*l + 7]))
    #define SV9  (__ldg(&Subject[base + 28*l + 8]))
    #define SV10  (__ldg(&Subject[base + 28*l + 9]))
    #define SV11  (__ldg(&Subject[base + 28*l + 10]))
    #define SV12  (__ldg(&Subject[base + 28*l + 11]))
    #define SV13  (__ldg(&Subject[base + 28*l + 12]))
    #define SV14  (__ldg(&Subject[base + 28*l + 13]))
    #define SV15  (__ldg(&Subject[base + 28*l + 14]))
    #define SV16  (__ldg(&Subject[base + 28*l + 15]))
    #define SV17  (__ldg(&Subject[base + 28*l + 16]))
    #define SV18  (__ldg(&Subject[base + 28*l + 17]))
    #define SV19  (__ldg(&Subject[base + 28*l + 18]))
    #define SV20  (__ldg(&Subject[base + 28*l + 19]))
    #define SV21  (__ldg(&Subject[base + 28*l + 20]))
    #define SV22  (__ldg(&Subject[base + 28*l + 21]))
    #define SV23  (__ldg(&Subject[base + 28*l + 22]))
    #define SV24  (__ldg(&Subject[base + 28*l + 23]))
    #define SV25  (__ldg(&Subject[base + 28*l + 24]))
    #define SV26  (__ldg(&Subject[base + 28*l + 25]))
    #define SV27  (__ldg(&Subject[base + 28*l + 26]))
    #define SV28  (__ldg(&Subject[base + 28*l + 27]))
#else
    const value_t sv0 = (l==0) ? (value_t)0 : Subject[base + 28*l - 1];
    const value_t sv1 = Subject[base + 28*l + 0];
    const value_t sv2 = Subject[base + 28*l + 1];
    const value_t sv3 = Subject[base + 28*l + 2];
    const value_t sv4 = Subject[base + 28*l + 3];
    const value_t sv5 = Subject[base + 28*l + 4];
    const value_t sv6 = Subject[base + 28*l + 5];
    const value_t sv7 = Subject[base + 28*l + 6];
    const value_t sv8 = Subject[base + 28*l + 7];
    const value_t sv9 = Subject[base + 28*l + 8];
    const value_t sv10 = Subject[base + 28*l + 9];
    const value_t sv11 = Subject[base + 28*l + 10];
    const value_t sv12 = Subject[base + 28*l + 11];
    const value_t sv13 = Subject[base + 28*l + 12];
    const value_t sv14 = Subject[base + 28*l + 13];
    const value_t sv15 = Subject[base + 28*l + 14];
    const value_t sv16 = Subject[base + 28*l + 15];
    const value_t sv17 = Subject[base + 28*l + 16];
    const value_t sv18 = Subject[base + 28*l + 17];
    const value_t sv19 = Subject[base + 28*l + 18];
    const value_t sv20 = Subject[base + 28*l + 19];
    const value_t sv21 = Subject[base + 28*l + 20];
    const value_t sv22 = Subject[base + 28*l + 21];
    const value_t sv23 = Subject[base + 28*l + 22];
    const value_t sv24 = Subject[base + 28*l + 23];
    const value_t sv25 = Subject[base + 28*l + 24];
    const value_t sv26 = Subject[base + 28*l + 25];
    const value_t sv27 = Subject[base + 28*l + 26];
    const value_t sv28 = Subject[base + 28*l + 27];
    #define SV0  sv0
    #define SV1  sv1
    #define SV2  sv2
    #define SV3  sv3
    #define SV4  sv4
    #define SV5  sv5
    #define SV6  sv6
    #define SV7  sv7
    #define SV8  sv8
    #define SV9  sv9
    #define SV10  sv10
    #define SV11  sv11
    #define SV12  sv12
    #define SV13  sv13
    #define SV14  sv14
    #define SV15  sv15
    #define SV16  sv16
    #define SV17  sv17
    #define SV18  sv18
    #define SV19  sv19
    #define SV20  sv20
    #define SV21  sv21
    #define SV22  sv22
    #define SV23  sv23
    #define SV24  sv24
    #define SV25  sv25
    #define SV26  sv26
    #define SV27  sv27
    #define SV28  sv28
#endif

    const int tgt_t = (int)(L_subject / 28);
    const int tgt_r = (int)(L_subject % 28);
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t cnt = 1;
    value_t qv = INFINITY, nqv = cQuery[thid];
    if (thid == 0) qv = nqv;
    if (thid == 0 && !left_bnd) penalty_here1 = (value_t)0;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);

    // ── Tile left-boundary (seam) injection ──────────────────────────
    // FIX (tiled boundary #1,#2): the seam left_bnd[i] = dp[i][last_col
    // of previous tile] must become the LEFT neighbour of this tile's
    // real column 0. Real col 0 is penalty_here1 on lane 0; its left
    // neighbour is penalty_here0 on lane 0 (the phantom sv0=0 column).
    // So we OVERWRITE penalty_here0 on lane 0 with seam[row] right after
    // it is recomputed each anti-diagonal. Schedule (proven in sim):
    //   pre-loop      -> row 0
    //   main loop k   -> row (k-2)
    // The diagonal for col 0 at row i is then seam[i-1], which arrives
    // automatically via penalty_temp0 (= previous step's penalty_here0).

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)(0);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = INFINITY;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_temp0 = penalty_here24;
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
        penalty_temp1 = penalty_here25;
        penalty_here25 = (qv-SV25)*(qv-SV25) + min(penalty_here24, min(penalty_here25, penalty_temp0));
        penalty_temp0 = penalty_here26;
        penalty_here26 = (qv-SV26)*(qv-SV26) + min(penalty_here25, min(penalty_here26, penalty_temp1));
        penalty_here27 = (qv-SV27)*(qv-SV27) + min(penalty_here26, min(penalty_here27, penalty_temp0));
    qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
    if (thid == 0) qv = nqv;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
    cnt++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here27, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (cnt % 32 == 0) nqv = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)((int)k - 2);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = penalty_here1;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_temp0 = penalty_here24;
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
        penalty_temp1 = penalty_here25;
        penalty_here25 = (qv-SV25)*(qv-SV25) + min(penalty_here24, min(penalty_here25, penalty_temp0));
        penalty_temp0 = penalty_here26;
        penalty_here26 = (qv-SV26)*(qv-SV26) + min(penalty_here25, min(penalty_here26, penalty_temp1));
        penalty_here27 = (qv-SV27)*(qv-SV27) + min(penalty_here26, min(penalty_here27, penalty_temp0));
        // Write right boundary from thread 31 (last real col of tile)
        if (thid == 31 && right_bnd) {
            int rr = (int)k - 2 - 31;
            if (rr >= 0 && rr < Lq) right_bnd[blid * Lq + rr] = penalty_here27;
        }
        qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
        if (thid == 0) qv = nqv;
        nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
        cnt++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here27, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    { value_t result = (value_t)0;
      if ((int)thid == tgt_t) {
          if (tgt_r == 0) result = penalty_here0;
          if (tgt_r == 1) result = penalty_here1;
          if (tgt_r == 2) result = penalty_here2;
          if (tgt_r == 3) result = penalty_here3;
          if (tgt_r == 4) result = penalty_here4;
          if (tgt_r == 5) result = penalty_here5;
          if (tgt_r == 6) result = penalty_here6;
          if (tgt_r == 7) result = penalty_here7;
          if (tgt_r == 8) result = penalty_here8;
          if (tgt_r == 9) result = penalty_here9;
          if (tgt_r == 10) result = penalty_here10;
          if (tgt_r == 11) result = penalty_here11;
          if (tgt_r == 12) result = penalty_here12;
          if (tgt_r == 13) result = penalty_here13;
          if (tgt_r == 14) result = penalty_here14;
          if (tgt_r == 15) result = penalty_here15;
          if (tgt_r == 16) result = penalty_here16;
          if (tgt_r == 17) result = penalty_here17;
          if (tgt_r == 18) result = penalty_here18;
          if (tgt_r == 19) result = penalty_here19;
          if (tgt_r == 20) result = penalty_here20;
          if (tgt_r == 21) result = penalty_here21;
          if (tgt_r == 22) result = penalty_here22;
          if (tgt_r == 23) result = penalty_here23;
          if (tgt_r == 24) result = penalty_here24;
          if (tgt_r == 25) result = penalty_here25;
          if (tgt_r == 26) result = penalty_here26;
          if (tgt_r == 27) result = penalty_here27;
      }
      result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
    }
}
#undef SV0
#undef SV1
#undef SV2
#undef SV3
#undef SV4
#undef SV5
#undef SV6
#undef SV7
#undef SV8
#undef SV9
#undef SV10
#undef SV11
#undef SV12
#undef SV13
#undef SV14
#undef SV15
#undef SV16
#undef SV17
#undef SV18
#undef SV19
#undef SV20
#undef SV21
#undef SV22
#undef SV23
#undef SV24
#undef SV25
#undef SV26
#undef SV27
#undef SV28

// K= 29  [intermediate: left+right bnd]
template<typename index_t,typename value_t> __global__
__launch_bounds__(32*CUDTW_TILED_WARPS_PER_BLOCK, CUDTW_TILED_MIN_BLOCKS)
void shfl_FullDTW_Tiled_K29_RW_impl(
    const value_t* __restrict__ Subject, value_t* __restrict__ Dist,
    index_t N, index_t L_query, index_t L_subject, index_t padded_stride,
    const value_t* __restrict__ left_bnd, value_t* __restrict__ right_bnd)
{
    // Multi-warp blocks (item #6): one warp per sequence; lane is intra-warp.
    const index_t lane = threadIdx.x & 31u;
    const index_t warp_in_block = threadIdx.x >> 5;
    const index_t blid = (index_t)blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    if (blid >= N) return;
    const index_t thid=lane, l=lane;
    const index_t base = blid * padded_stride;
    const int Lq = (int)L_query;

    value_t penalty_here0 = INFINITY;
    value_t penalty_here1 = INFINITY;
    value_t penalty_here2 = INFINITY;
    value_t penalty_here3 = INFINITY;
    value_t penalty_here4 = INFINITY;
    value_t penalty_here5 = INFINITY;
    value_t penalty_here6 = INFINITY;
    value_t penalty_here7 = INFINITY;
    value_t penalty_here8 = INFINITY;
    value_t penalty_here9 = INFINITY;
    value_t penalty_here10 = INFINITY;
    value_t penalty_here11 = INFINITY;
    value_t penalty_here12 = INFINITY;
    value_t penalty_here13 = INFINITY;
    value_t penalty_here14 = INFINITY;
    value_t penalty_here15 = INFINITY;
    value_t penalty_here16 = INFINITY;
    value_t penalty_here17 = INFINITY;
    value_t penalty_here18 = INFINITY;
    value_t penalty_here19 = INFINITY;
    value_t penalty_here20 = INFINITY;
    value_t penalty_here21 = INFINITY;
    value_t penalty_here22 = INFINITY;
    value_t penalty_here23 = INFINITY;
    value_t penalty_here24 = INFINITY;
    value_t penalty_here25 = INFINITY;
    value_t penalty_here26 = INFINITY;
    value_t penalty_here27 = INFINITY;
    value_t penalty_here28 = INFINITY;
    value_t penalty_left=INFINITY, penalty_diag=0, penalty_temp0, penalty_temp1;
    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
        penalty_here2 = INFINITY;
        penalty_here3 = INFINITY;
        penalty_here4 = INFINITY;
        penalty_here5 = INFINITY;
        penalty_here6 = INFINITY;
        penalty_here7 = INFINITY;
        penalty_here8 = INFINITY;
        penalty_here9 = INFINITY;
        penalty_here10 = INFINITY;
        penalty_here11 = INFINITY;
        penalty_here12 = INFINITY;
        penalty_here13 = INFINITY;
        penalty_here14 = INFINITY;
        penalty_here15 = INFINITY;
        penalty_here16 = INFINITY;
        penalty_here17 = INFINITY;
        penalty_here18 = INFINITY;
        penalty_here19 = INFINITY;
        penalty_here20 = INFINITY;
        penalty_here21 = INFINITY;
        penalty_here22 = INFINITY;
        penalty_here23 = INFINITY;
        penalty_here24 = INFINITY;
        penalty_here25 = INFINITY;
        penalty_here26 = INFINITY;
        penalty_here27 = INFINITY;
        penalty_here28 = INFINITY;
    }

#if CUDTW_TILED_LDG_SUBJECT
    #define SV0  ((l==0) ? (value_t)0 : __ldg(&Subject[base + 29*l - 1]))
    #define SV1  (__ldg(&Subject[base + 29*l + 0]))
    #define SV2  (__ldg(&Subject[base + 29*l + 1]))
    #define SV3  (__ldg(&Subject[base + 29*l + 2]))
    #define SV4  (__ldg(&Subject[base + 29*l + 3]))
    #define SV5  (__ldg(&Subject[base + 29*l + 4]))
    #define SV6  (__ldg(&Subject[base + 29*l + 5]))
    #define SV7  (__ldg(&Subject[base + 29*l + 6]))
    #define SV8  (__ldg(&Subject[base + 29*l + 7]))
    #define SV9  (__ldg(&Subject[base + 29*l + 8]))
    #define SV10  (__ldg(&Subject[base + 29*l + 9]))
    #define SV11  (__ldg(&Subject[base + 29*l + 10]))
    #define SV12  (__ldg(&Subject[base + 29*l + 11]))
    #define SV13  (__ldg(&Subject[base + 29*l + 12]))
    #define SV14  (__ldg(&Subject[base + 29*l + 13]))
    #define SV15  (__ldg(&Subject[base + 29*l + 14]))
    #define SV16  (__ldg(&Subject[base + 29*l + 15]))
    #define SV17  (__ldg(&Subject[base + 29*l + 16]))
    #define SV18  (__ldg(&Subject[base + 29*l + 17]))
    #define SV19  (__ldg(&Subject[base + 29*l + 18]))
    #define SV20  (__ldg(&Subject[base + 29*l + 19]))
    #define SV21  (__ldg(&Subject[base + 29*l + 20]))
    #define SV22  (__ldg(&Subject[base + 29*l + 21]))
    #define SV23  (__ldg(&Subject[base + 29*l + 22]))
    #define SV24  (__ldg(&Subject[base + 29*l + 23]))
    #define SV25  (__ldg(&Subject[base + 29*l + 24]))
    #define SV26  (__ldg(&Subject[base + 29*l + 25]))
    #define SV27  (__ldg(&Subject[base + 29*l + 26]))
    #define SV28  (__ldg(&Subject[base + 29*l + 27]))
    #define SV29  (__ldg(&Subject[base + 29*l + 28]))
#else
    const value_t sv0 = (l==0) ? (value_t)0 : Subject[base + 29*l - 1];
    const value_t sv1 = Subject[base + 29*l + 0];
    const value_t sv2 = Subject[base + 29*l + 1];
    const value_t sv3 = Subject[base + 29*l + 2];
    const value_t sv4 = Subject[base + 29*l + 3];
    const value_t sv5 = Subject[base + 29*l + 4];
    const value_t sv6 = Subject[base + 29*l + 5];
    const value_t sv7 = Subject[base + 29*l + 6];
    const value_t sv8 = Subject[base + 29*l + 7];
    const value_t sv9 = Subject[base + 29*l + 8];
    const value_t sv10 = Subject[base + 29*l + 9];
    const value_t sv11 = Subject[base + 29*l + 10];
    const value_t sv12 = Subject[base + 29*l + 11];
    const value_t sv13 = Subject[base + 29*l + 12];
    const value_t sv14 = Subject[base + 29*l + 13];
    const value_t sv15 = Subject[base + 29*l + 14];
    const value_t sv16 = Subject[base + 29*l + 15];
    const value_t sv17 = Subject[base + 29*l + 16];
    const value_t sv18 = Subject[base + 29*l + 17];
    const value_t sv19 = Subject[base + 29*l + 18];
    const value_t sv20 = Subject[base + 29*l + 19];
    const value_t sv21 = Subject[base + 29*l + 20];
    const value_t sv22 = Subject[base + 29*l + 21];
    const value_t sv23 = Subject[base + 29*l + 22];
    const value_t sv24 = Subject[base + 29*l + 23];
    const value_t sv25 = Subject[base + 29*l + 24];
    const value_t sv26 = Subject[base + 29*l + 25];
    const value_t sv27 = Subject[base + 29*l + 26];
    const value_t sv28 = Subject[base + 29*l + 27];
    const value_t sv29 = Subject[base + 29*l + 28];
    #define SV0  sv0
    #define SV1  sv1
    #define SV2  sv2
    #define SV3  sv3
    #define SV4  sv4
    #define SV5  sv5
    #define SV6  sv6
    #define SV7  sv7
    #define SV8  sv8
    #define SV9  sv9
    #define SV10  sv10
    #define SV11  sv11
    #define SV12  sv12
    #define SV13  sv13
    #define SV14  sv14
    #define SV15  sv15
    #define SV16  sv16
    #define SV17  sv17
    #define SV18  sv18
    #define SV19  sv19
    #define SV20  sv20
    #define SV21  sv21
    #define SV22  sv22
    #define SV23  sv23
    #define SV24  sv24
    #define SV25  sv25
    #define SV26  sv26
    #define SV27  sv27
    #define SV28  sv28
    #define SV29  sv29
#endif

    const int tgt_t = (int)(L_subject / 29);
    const int tgt_r = (int)(L_subject % 29);
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t cnt = 1;
    value_t qv = INFINITY, nqv = cQuery[thid];
    if (thid == 0) qv = nqv;
    if (thid == 0 && !left_bnd) penalty_here1 = (value_t)0;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);

    // ── Tile left-boundary (seam) injection ──────────────────────────
    // FIX (tiled boundary #1,#2): the seam left_bnd[i] = dp[i][last_col
    // of previous tile] must become the LEFT neighbour of this tile's
    // real column 0. Real col 0 is penalty_here1 on lane 0; its left
    // neighbour is penalty_here0 on lane 0 (the phantom sv0=0 column).
    // So we OVERWRITE penalty_here0 on lane 0 with seam[row] right after
    // it is recomputed each anti-diagonal. Schedule (proven in sim):
    //   pre-loop      -> row 0
    //   main loop k   -> row (k-2)
    // The diagonal for col 0 at row i is then seam[i-1], which arrives
    // automatically via penalty_temp0 (= previous step's penalty_here0).

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)(0);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = INFINITY;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_temp0 = penalty_here24;
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
        penalty_temp1 = penalty_here25;
        penalty_here25 = (qv-SV25)*(qv-SV25) + min(penalty_here24, min(penalty_here25, penalty_temp0));
        penalty_temp0 = penalty_here26;
        penalty_here26 = (qv-SV26)*(qv-SV26) + min(penalty_here25, min(penalty_here26, penalty_temp1));
        penalty_temp1 = penalty_here27;
        penalty_here27 = (qv-SV27)*(qv-SV27) + min(penalty_here26, min(penalty_here27, penalty_temp0));
        penalty_here28 = (qv-SV28)*(qv-SV28) + min(penalty_here27, min(penalty_here28, penalty_temp1));
    qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
    if (thid == 0) qv = nqv;
    nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
    cnt++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here28, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (cnt % 32 == 0) nqv = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (qv-SV0)*(qv-SV0) + min(penalty_left, min(penalty_here0, penalty_diag));
        if (thid == 0 && left_bnd) {
            const int _row = (int)((int)k - 2);
            penalty_here0 = (_row >= 0 && _row < Lq)
                            ? left_bnd[blid * Lq + _row] : INFINITY;
        }
        penalty_temp1 = penalty_here1;
        penalty_here1 = (qv-SV1)*(qv-SV1) + min(penalty_here0, min(penalty_here1, penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (qv-SV2)*(qv-SV2) + min(penalty_here1, min(penalty_here2, penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (qv-SV3)*(qv-SV3) + min(penalty_here2, min(penalty_here3, penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (qv-SV4)*(qv-SV4) + min(penalty_here3, min(penalty_here4, penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (qv-SV5)*(qv-SV5) + min(penalty_here4, min(penalty_here5, penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (qv-SV6)*(qv-SV6) + min(penalty_here5, min(penalty_here6, penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (qv-SV7)*(qv-SV7) + min(penalty_here6, min(penalty_here7, penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (qv-SV8)*(qv-SV8) + min(penalty_here7, min(penalty_here8, penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (qv-SV9)*(qv-SV9) + min(penalty_here8, min(penalty_here9, penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (qv-SV10)*(qv-SV10) + min(penalty_here9, min(penalty_here10, penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (qv-SV11)*(qv-SV11) + min(penalty_here10, min(penalty_here11, penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (qv-SV12)*(qv-SV12) + min(penalty_here11, min(penalty_here12, penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (qv-SV13)*(qv-SV13) + min(penalty_here12, min(penalty_here13, penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (qv-SV14)*(qv-SV14) + min(penalty_here13, min(penalty_here14, penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (qv-SV15)*(qv-SV15) + min(penalty_here14, min(penalty_here15, penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (qv-SV16)*(qv-SV16) + min(penalty_here15, min(penalty_here16, penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (qv-SV17)*(qv-SV17) + min(penalty_here16, min(penalty_here17, penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (qv-SV18)*(qv-SV18) + min(penalty_here17, min(penalty_here18, penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (qv-SV19)*(qv-SV19) + min(penalty_here18, min(penalty_here19, penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (qv-SV20)*(qv-SV20) + min(penalty_here19, min(penalty_here20, penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (qv-SV21)*(qv-SV21) + min(penalty_here20, min(penalty_here21, penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (qv-SV22)*(qv-SV22) + min(penalty_here21, min(penalty_here22, penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (qv-SV23)*(qv-SV23) + min(penalty_here22, min(penalty_here23, penalty_temp0));
        penalty_temp0 = penalty_here24;
        penalty_here24 = (qv-SV24)*(qv-SV24) + min(penalty_here23, min(penalty_here24, penalty_temp1));
        penalty_temp1 = penalty_here25;
        penalty_here25 = (qv-SV25)*(qv-SV25) + min(penalty_here24, min(penalty_here25, penalty_temp0));
        penalty_temp0 = penalty_here26;
        penalty_here26 = (qv-SV26)*(qv-SV26) + min(penalty_here25, min(penalty_here26, penalty_temp1));
        penalty_temp1 = penalty_here27;
        penalty_here27 = (qv-SV27)*(qv-SV27) + min(penalty_here26, min(penalty_here27, penalty_temp0));
        penalty_here28 = (qv-SV28)*(qv-SV28) + min(penalty_here27, min(penalty_here28, penalty_temp1));
        // Write right boundary from thread 31 (last real col of tile)
        if (thid == 31 && right_bnd) {
            int rr = (int)k - 2 - 31;
            if (rr >= 0 && rr < Lq) right_bnd[blid * Lq + rr] = penalty_here28;
        }
        qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
        if (thid == 0) qv = nqv;
        nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
        cnt++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here28, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    { value_t result = (value_t)0;
      if ((int)thid == tgt_t) {
          if (tgt_r == 0) result = penalty_here0;
          if (tgt_r == 1) result = penalty_here1;
          if (tgt_r == 2) result = penalty_here2;
          if (tgt_r == 3) result = penalty_here3;
          if (tgt_r == 4) result = penalty_here4;
          if (tgt_r == 5) result = penalty_here5;
          if (tgt_r == 6) result = penalty_here6;
          if (tgt_r == 7) result = penalty_here7;
          if (tgt_r == 8) result = penalty_here8;
          if (tgt_r == 9) result = penalty_here9;
          if (tgt_r == 10) result = penalty_here10;
          if (tgt_r == 11) result = penalty_here11;
          if (tgt_r == 12) result = penalty_here12;
          if (tgt_r == 13) result = penalty_here13;
          if (tgt_r == 14) result = penalty_here14;
          if (tgt_r == 15) result = penalty_here15;
          if (tgt_r == 16) result = penalty_here16;
          if (tgt_r == 17) result = penalty_here17;
          if (tgt_r == 18) result = penalty_here18;
          if (tgt_r == 19) result = penalty_here19;
          if (tgt_r == 20) result = penalty_here20;
          if (tgt_r == 21) result = penalty_here21;
          if (tgt_r == 22) result = penalty_here22;
          if (tgt_r == 23) result = penalty_here23;
          if (tgt_r == 24) result = penalty_here24;
          if (tgt_r == 25) result = penalty_here25;
          if (tgt_r == 26) result = penalty_here26;
          if (tgt_r == 27) result = penalty_here27;
          if (tgt_r == 28) result = penalty_here28;
      }
      result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
    }
}
#undef SV0
#undef SV1
#undef SV2
#undef SV3
#undef SV4
#undef SV5
#undef SV6
