    #define SV32  (__ldg(&Subject[base + 32*l + 31]))
#else
    const value_t sv0 = (l==0) ? (value_t)0 : Subject[base + 32*l - 1];
    const value_t sv1 = Subject[base + 32*l + 0];
    const value_t sv2 = Subject[base + 32*l + 1];
    const value_t sv3 = Subject[base + 32*l + 2];
    const value_t sv4 = Subject[base + 32*l + 3];
    const value_t sv5 = Subject[base + 32*l + 4];
