          if (tgt_r == 33) result = penalty_here33;
          if (tgt_r == 34) result = penalty_here34;
          if (tgt_r == 35) result = penalty_here35;
      }
      result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
    }
