        penalty_temp0 = penalty_here38;
        penalty_here38 = (qv-SV38)*(qv-SV38) + min(penalty_here37, min(penalty_here38, penalty_temp1));
        penalty_temp1 = penalty_here39;
        penalty_here39 = (qv-SV39)*(qv-SV39) + min(penalty_here38, min(penalty_here39, penalty_temp0));
        penalty_here40 = (qv-SV40)*(qv-SV40) + min(penalty_here39, min(penalty_here40, penalty_temp1));
