        penalty_temp0 = penalty_here40;
        penalty_here40 = (qv-SV40)*(qv-SV40) + min(penalty_here39, min(penalty_here40, penalty_temp1));
        penalty_temp1 = penalty_here41;
        penalty_here41 = (qv-SV41)*(qv-SV41) + min(penalty_here40, min(penalty_here41, penalty_temp0));
        penalty_temp0 = penalty_here42;
        penalty_here42 = (qv-SV42)*(qv-SV42) + min(penalty_here41, min(penalty_here42, penalty_temp1));
        penalty_temp1 = penalty_here43;
        penalty_here43 = (qv-SV43)*(qv-SV43) + min(penalty_here42, min(penalty_here43, penalty_temp0));
        penalty_temp0 = penalty_here44;
        penalty_here44 = (qv-SV44)*(qv-SV44) + min(penalty_here43, min(penalty_here44, penalty_temp1));
        penalty_here45 = (qv-SV45)*(qv-SV45) + min(penalty_here44, min(penalty_here45, penalty_temp0));
        // Write right boundary from thread 31 (last real col of tile)
        if (thid == 31 && right_bnd) {
            int rr = (int)k - 2 - 31;
            if (rr >= 0 && rr < Lq) right_bnd[blid * Lq + rr] = penalty_here45;
        }
        qv  = __shfl_up_sync(0xFFFFFFFF, qv, 1, 32);
        if (thid == 0) qv = nqv;
        nqv = __shfl_down_sync(0xFFFFFFFF, nqv, 1, 32);
        cnt++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here45, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    { value_t result = (value_t)0;
