        penalty_here49 = (qv-SV49)*(qv-SV49) + min(penalty_here48, min(penalty_here49, penalty_temp0));
        // Write right boundary from thread 31 (last real col of tile)
        if (thid == 31 && right_bnd) {
            int rr = (int)k - 2 - 31;
