    #define SV14  (__ldg(&Subject[base + 22*l + 13]))
    #define SV15  (__ldg(&Subject[base + 22*l + 14]))
    #define SV16  (__ldg(&Subject[base + 22*l + 15]))
    #define SV17  (__ldg(&Subject[base + 22*l + 16]))
    #define SV18  (__ldg(&Subject[base + 22*l + 17]))
    #define SV19  (__ldg(&Subject[base + 22*l + 18]))
    #define SV20  (__ldg(&Subject[base + 22*l + 19]))
