    const value_t sv2 = Subject[base + 22*l + 1];
    const value_t sv3 = Subject[base + 22*l + 2];
    const value_t sv4 = Subject[base + 22*l + 3];
    const value_t sv5 = Subject[base + 22*l + 4];
