    const value_t sv7 = Subject[base + 22*l + 6];
    const value_t sv8 = Subject[base + 22*l + 7];
    const value_t sv9 = Subject[base + 22*l + 8];
    const value_t sv10 = Subject[base + 22*l + 9];
    const value_t sv11 = Subject[base + 22*l + 10];
    const value_t sv12 = Subject[base + 22*l + 11];
