        penalty_here37 = INFINITY;
        penalty_here38 = INFINITY;
    }

#if CUDTW_TILED_LDG_SUBJECT
    #define SV0  ((l==0) ? (value_t)0 : __ldg(&Subject[base + 39*l - 1]))
    #define SV1  (__ldg(&Subject[base + 39*l + 0]))
    #define SV2  (__ldg(&Subject[base + 39*l + 1]))
    #define SV3  (__ldg(&Subject[base + 39*l + 2]))
    #define SV4  (__ldg(&Subject[base + 39*l + 3]))
    #define SV5  (__ldg(&Subject[base + 39*l + 4]))
    #define SV6  (__ldg(&Subject[base + 39*l + 5]))
    #define SV7  (__ldg(&Subject[base + 39*l + 6]))
    #define SV8  (__ldg(&Subject[base + 39*l + 7]))
    #define SV9  (__ldg(&Subject[base + 39*l + 8]))
    #define SV10  (__ldg(&Subject[base + 39*l + 9]))
    #define SV11  (__ldg(&Subject[base + 39*l + 10]))
    #define SV12  (__ldg(&Subject[base + 39*l + 11]))
    #define SV13  (__ldg(&Subject[base + 39*l + 12]))
    #define SV14  (__ldg(&Subject[base + 39*l + 13]))
    #define SV15  (__ldg(&Subject[base + 39*l + 14]))
    #define SV16  (__ldg(&Subject[base + 39*l + 15]))
    #define SV17  (__ldg(&Subject[base + 39*l + 16]))
    #define SV18  (__ldg(&Subject[base + 39*l + 17]))
    #define SV19  (__ldg(&Subject[base + 39*l + 18]))
    #define SV20  (__ldg(&Subject[base + 39*l + 19]))
    #define SV21  (__ldg(&Subject[base + 39*l + 20]))
    #define SV22  (__ldg(&Subject[base + 39*l + 21]))
    #define SV23  (__ldg(&Subject[base + 39*l + 22]))
    #define SV24  (__ldg(&Subject[base + 39*l + 23]))
    #define SV25  (__ldg(&Subject[base + 39*l + 24]))
    #define SV26  (__ldg(&Subject[base + 39*l + 25]))
    #define SV27  (__ldg(&Subject[base + 39*l + 26]))
    #define SV28  (__ldg(&Subject[base + 39*l + 27]))
    #define SV29  (__ldg(&Subject[base + 39*l + 28]))
    #define SV30  (__ldg(&Subject[base + 39*l + 29]))
    #define SV31  (__ldg(&Subject[base + 39*l + 30]))
    #define SV32  (__ldg(&Subject[base + 39*l + 31]))
    #define SV33  (__ldg(&Subject[base + 39*l + 32]))
    #define SV34  (__ldg(&Subject[base + 39*l + 33]))
    #define SV35  (__ldg(&Subject[base + 39*l + 34]))
    #define SV36  (__ldg(&Subject[base + 39*l + 35]))
    #define SV37  (__ldg(&Subject[base + 39*l + 36]))
    #define SV38  (__ldg(&Subject[base + 39*l + 37]))
    #define SV39  (__ldg(&Subject[base + 39*l + 38]))
#else
    const value_t sv0 = (l==0) ? (value_t)0 : Subject[base + 39*l - 1];
    const value_t sv1 = Subject[base + 39*l + 0];
    const value_t sv2 = Subject[base + 39*l + 1];
    const value_t sv3 = Subject[base + 39*l + 2];
    const value_t sv4 = Subject[base + 39*l + 3];
    const value_t sv5 = Subject[base + 39*l + 4];
    const value_t sv6 = Subject[base + 39*l + 5];
    const value_t sv7 = Subject[base + 39*l + 6];
    const value_t sv8 = Subject[base + 39*l + 7];
    const value_t sv9 = Subject[base + 39*l + 8];
    const value_t sv10 = Subject[base + 39*l + 9];
    const value_t sv11 = Subject[base + 39*l + 10];
    const value_t sv12 = Subject[base + 39*l + 11];
    const value_t sv13 = Subject[base + 39*l + 12];
    const value_t sv14 = Subject[base + 39*l + 13];
    const value_t sv15 = Subject[base + 39*l + 14];
    const value_t sv16 = Subject[base + 39*l + 15];
    const value_t sv17 = Subject[base + 39*l + 16];
    const value_t sv18 = Subject[base + 39*l + 17];
    const value_t sv19 = Subject[base + 39*l + 18];
    const value_t sv20 = Subject[base + 39*l + 19];
    const value_t sv21 = Subject[base + 39*l + 20];
    const value_t sv22 = Subject[base + 39*l + 21];
    const value_t sv23 = Subject[base + 39*l + 22];
    const value_t sv24 = Subject[base + 39*l + 23];
    const value_t sv25 = Subject[base + 39*l + 24];
    const value_t sv26 = Subject[base + 39*l + 25];
    const value_t sv27 = Subject[base + 39*l + 26];
    const value_t sv28 = Subject[base + 39*l + 27];
    const value_t sv29 = Subject[base + 39*l + 28];
    const value_t sv30 = Subject[base + 39*l + 29];
    const value_t sv31 = Subject[base + 39*l + 30];
    const value_t sv32 = Subject[base + 39*l + 31];
    const value_t sv33 = Subject[base + 39*l + 32];
    const value_t sv34 = Subject[base + 39*l + 33];
    const value_t sv35 = Subject[base + 39*l + 34];
    const value_t sv36 = Subject[base + 39*l + 35];
    const value_t sv37 = Subject[base + 39*l + 36];
    const value_t sv38 = Subject[base + 39*l + 37];
    const value_t sv39 = Subject[base + 39*l + 38];
    #define SV0  sv0
    #define SV1  sv1
    #define SV2  sv2
    #define SV3  sv3
    #define SV4  sv4
    #define SV5  sv5
    #define SV6  sv6
    #define SV7  sv7
    #define SV8  sv8
    #define SV9  sv9
    #define SV10  sv10
    #define SV11  sv11
