        penalty_here51 = (qv-SV51)*(qv-SV51) + min(penalty_here50, min(penalty_here51, penalty_temp0));
        penalty_temp0 = penalty_here52;
        penalty_here52 = (qv-SV52)*(qv-SV52) + min(penalty_here51, min(penalty_here52, penalty_temp1));
        penalty_temp1 = penalty_here53;
        penalty_here53 = (qv-SV53)*(qv-SV53) + min(penalty_here52, min(penalty_here53, penalty_temp0));
        penalty_here54 = (qv-SV54)*(qv-SV54) + min(penalty_here53, min(penalty_here54, penalty_temp1));
